import { Contract, isAddress } from "ethers";
import { TARGET_CHAIN_ID } from "./chains.js";
// These files are generated by the contracts project (npm run deploy:local /
// npm run export-abi). Add Sepolia addresses to deployments.json by hand after
// deploying with Remix, under the key "11155111".
import deployments from "./deployments.json";
import gameCoinAbi from "./abi/GameCoin.json";
import elementCardsAbi from "./abi/ElementCards.json";
import arenaAbi from "./abi/Arena.json";

const addresses = deployments[String(TARGET_CHAIN_ID)] ?? {};

export const COIN_ADDRESS = addresses.GameCoin ?? "";
export const CARDS_ADDRESS = addresses.ElementCards ?? "";
export const ARENA_ADDRESS = addresses.Arena ?? "";
export const contractsConfigured =
  isAddress(COIN_ADDRESS) && isAddress(CARDS_ADDRESS) && isAddress(ARENA_ADDRESS);

// Pass a provider for free reads, or a signer for transactions.
export function getCoinContract(runner) {
  return new Contract(COIN_ADDRESS, gameCoinAbi, runner);
}

export function getCardsContract(runner) {
  return new Contract(CARDS_ADDRESS, elementCardsAbi, runner);
}

export function getArenaContract(runner) {
  return new Contract(ARENA_ADDRESS, arenaAbi, runner);
}

// Solidity enums arrive as numbers. These arrays use the same order as the contracts.
export const ELEMENTS = ["Neutral", "Fire", "Water", "Grass", "Electric", "Ground", "Ice", "Dragon", "Dark"];
export const RARITIES = ["Common", "Rare", "Legendary"];
export const PASSIVES = ["None", "Pierce", "Underdog", "Resonance", "Guard", "Focus"];
export const GENDERS = ["Male", "Female"];
export const GENDER_SYMBOLS = ["♂", "♀"];
export const BATTLE_STATUS = ["None", "Open", "Joined", "Resolved", "Cancelled"];

// What each passive does in battle. Mirrors Arena.battlePower.
export const PASSIVE_EFFECTS = {
  Pierce: "A resisted attack still deals full damage.",
  Underdog: "+30% power against a stronger card.",
  Resonance: "+20% power when both cards share an element.",
  Guard: "+25% power when the enemy is strong against this card.",
  Focus: "+10% power in every battle.",
};

// Prices in coins, indexed by rarity. Mirror ElementCards; the Rules page reads the live values.
export const PACK_PRICE = 1_000n;
export const DECOMPOSE_VALUES = [300n, 900n, 2_700n];
export const ENCHANT_COSTS = [200n, 500n, 1_000n];
export const BREED_FEES = [500n, 1_500n, 4_500n];
